    private static List<Integer> generatePermutation(int n, long k) {
        List<Integer> permutation = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            permutation.add(i);
        }
        long current = k;
        for (int i = n - 1; i >= 1; i--) {
            long fact = factorial(i);
            int index = (int) ((current - 1) / fact);
            current = (current - 1) % fact + 1;
            // Swap the element at position (n - i - 1) with the element at position (n - i - 1 + index)
            int pos1 = n - i - 1;
            int pos2 = pos1 + index;
            int temp = permutation.get(pos1);
            permutation.set(pos1, permutation.get(pos2));
            permutation.set(pos2, temp);
        }
        return permutation;
    }

    private static long factorial(int n) {
        long result = 1;
        for (int i = 1; i <= n; i++) {
            result *= i;
        }
        return result;
    }
