    private static List<Integer> findKth(List<Integer> perm, long k) {
        if (perm.size() == 0) {
            return new ArrayList<>();
        }
        int m = perm.size();
        long[][] dp = new long[m + 1][m + 1];
        for (int i = 0; i <= m; i++) {
            dp[i][0] = 1;
        }
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= i; j++) {
                dp[i][j] = dp[i - 1][j - 1] + (i - 1) * dp[i - 1][j];
            }
        }
        long total = dp[m][m];
        if (k > total) {
            return null;
        }
        List<Integer> result = new ArrayList<>();
        List<Integer> current = new ArrayList<>(perm);
        long remaining = k;
        for (int i = 0; i < m; i++) {
            int len = current.size();
            long[][] ways = new long[len + 1][len + 1];
            for (int a = 0; a <= len; a++) {
                ways[a][0] = 1;
            }
            for (int a = 1; a <= len; a++) {
                for (int b = 1; b <= a; b++) {
                    ways[a][b] = ways[a - 1][b - 1] + (a - 1) * ways[a - 1][b];
                }
            }
            long sum = 0;
            for (int j = 0; j < len; j++) {
                int val = current.get(j);
                List<Integer> next = new ArrayList<>();
                for (int x : current) {
                    if (x != val) {
                        next.add(x);
                    }
                }
                long cnt = ways[len - 1][len - 1];
                if (sum + cnt >= remaining) {
                    result.add(val);
                    current = next;
                    break;
                }
                sum += cnt;
            }
        }
        return result;
    }
