import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static List<Integer> generatePermutation(int n, long k) {
        List<Integer> permutation = new ArrayList<>();
        boolean[] used = new boolean[n + 1];
        generate(n, k, 1, used, permutation);
        return permutation;
    }

    static long generate(int n, long k, int pos, boolean[] used, List<Integer> permutation) {
        if (pos > n) {
            return 1;
        }
        if (used[pos]) {
            permutation.add(pos);
            return generate(n, k, pos + 1, used, permutation);
        }
        long count = 0;
        for (int len = 1; pos + len - 1 <= n; len++) {
            int end = pos + len - 1;
            if (used[end]) {
                continue;
            }
            boolean valid = true;
            for (int i = pos; i < end; i++) {
                if (used[i]) {
                    valid = false;
                    break;
                }
            }
            if (!valid) {
                continue;
            }
            for (int i = pos; i <= end; i++) {
                used[i] = true;
            }
            permutation.add(end);
            for (int i = pos; i < end; i++) {
                permutation.add(i);
            }
            long res = generate(n, k, end + 1, used, permutation);
            if (count + res >= k) {
                return count + res;
            }
            count += res;
            for (int i = pos; i <= end; i++) {
                used[i] = false;
            }
            for (int i = 0; i < len; i++) {
                permutation.remove(permutation.size() - 1);
            }
        }
        return count;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        long k = scanner.nextLong();
        List<Integer> result = generatePermutation(n, k);
        for (int i = 0; i < result.size(); i++) {
