    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextLong();
        dp = new long[n+2][n+2];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = -1;
            }
        }
        List<Integer> res = solve(1, n);
        for (int x : res) System.out.print(x + " ");
        System.out.println();
    }

    static long count(int pos, int rem) {
        if (rem == 0) return 1;
        if (pos > n) return 0;
        if (dp[pos][rem] != -1) return dp[pos][rem];
        long res = 0;
        // Place a cycle of length 1 (fixed point)
        res += count(pos+1, rem-1);
        // Place a cycle of length >=2 starting at pos
        for (int len = 2; pos + len -1 <= n && len <= rem; len++) {
            res += count(pos+len, rem-len);
        }
        return dp[pos][rem] = res;
    }

    static List<Integer> solve(int pos, int rem) {
        List<Integer> res = new ArrayList<>();
        if (rem == 0) return res;
        // Try fixed point first
        long c = count(pos+1, rem-1);
        if (k <= c) {
            res.add(pos);
            res.addAll(solve(pos+1, rem-1));
            return res;
        }
        k -= c;
        // Try cycles of length >=2
        for (int len = 2; pos + len -1 <= n && len <= rem; len++) {
            c = count(pos+len, rem-len);
            if (k <= c) {
                // Build cycle: pos -> pos+1 -> ... -> pos+len-1 -> pos
                for (int i = 1; i < len; i++) res.add(pos+i);
                res.add(pos);
                res.addAll(solve(pos+len, rem-len));
                return res;
            }
            k -= c;
        }
        return res; // should not reach here
    }
}
