        cycles.clear();
        generateCycles(n);
        long total = 0;
        for (List<Integer> cycle : cycles) {
            total += countArrangements(cycle);
        }
        return total;
    }

    static void generateCycles(int n) {
        boolean[] visited = new boolean[n + 1];
        for (int i = 1; i <= n; i++) {
            if (!visited[i]) {
                List<Integer> cycle = new ArrayList<>();
                int current = i;
                while (!visited[current]) {
                    visited[current] = true;
                    cycle.add(current);
                    current = current % n + 1;
                }
                cycles.add(cycle);
            }
        }
    }

    static long countArrangements(List<Integer> cycle) {
        int m = cycle.size();
        if (m <= 1) return 1;
        long count = 1;
        for (int i = 1; i < m; i++) {
            count *= i;
        }
        return count;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        long k = scanner.nextLong();
        scanner.close();

        int[] permutation = new int[n];
        for (int i = 0; i < n; i++) {
            permutation[i] = i + 1;
        }

        List<int[]> validPermutations = new ArrayList<>();
        generatePermutations(permutation, 0, validPermutations);

        System.out.println(arrayToString(validPermutations.get((int) (k - 1))));
    }

    static void generatePermutations(int[] permutation, int index, List<int[]> validPermutations) {
        if (index == permutation.length) {
            if (isValid(permutation)) {
                validPermutations.add(permutation.clone());
            }
            return;
        }

        for (int i = index; i < permutation.length; i++) {
            swap(permutation, index, i);
            generatePermutations(permutation, index + 1, validPermutations);
            swap(permutation, index, i);
        }
    }

    static boolean isValid(int[] permutation) {
        int n = permutation.length;
        boolean[] visited = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                List<Integer> cycle = new ArrayList<>();
                int current = i;
                while (!visited[current]) {
                    visited[current] = true;
                    cycle.add(current + 1);
                    current = permutation[current] - 1;
                }
                if (!isStandardForm(cycle)) {
                    return false;
                }
            }
        }
        return true;
    }

    static boolean isStandardForm(List<Integer> cycle) {
        int maxIndex = 0;
        for (int i = 1; i < cycle.size(); i++) {
            if (cycle.get(i) > cycle.get(maxIndex)) {
                maxIndex = i;
            }
        }
        return maxIndex == 0;
    }

    static void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    static String arrayToString(int[] array) {
        StringBuilder sb = new StringBuilder();
        for (int num : array) {
            sb.append(num).append(" ");
        }
        return sb.toString().trim();
    }
