public class Main {
    static class Cycle implements Comparable<Cycle> {
        List<Integer> elements;
        int max;
        int first;

        Cycle(List<Integer> elements) {
            this.elements = elements;
            this.max = Collections.max(elements);
            this.first = elements.get(0);
        }

        @Override
        public int compareTo(Cycle other) {
            return Integer.compare(this.first, other.first);
        }
    }

    static List<Cycle> getStandardCycles(int[] perm) {
        int n = perm.length;
        boolean[] visited = new boolean[n + 1];
        List<Cycle> cycles = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            if (!visited[i]) {
                List<Integer> cycle = new ArrayList<>();
                int current = i;
                while (!visited[current]) {
                    visited[current] = true;
                    cycle.add(current);
                    current = perm[current - 1];
                }
                int max = Collections.max(cycle);
                int idx = cycle.indexOf(max);
                List<Integer> rotated = new ArrayList<>();
                for (int j = idx; j < cycle.size(); j++) {
                    rotated.add(cycle.get(j));
                }
                for (int j = 0; j < idx; j++) {
                    rotated.add(cycle.get(j));
                }
                cycles.add(new Cycle(rotated));
            }
        }
        Collections.sort(cycles);
        return cycles;
    }

    static int[] cyclesToPerm(List<Cycle> cycles, int n) {
        int[] perm = new int[n];
        for (Cycle cycle : cycles) {
            List<Integer> elements = cycle.elements;
            for (int i = 0; i < elements.size(); i++) {
                int current = elements.get(i);
                int next = elements.get((i + 1) % elements.size());
                perm[current - 1] = next;
            }
        }
        return perm;
    }

    static boolean isFixedPoint(int[] perm) {
        List<Cycle> cycles = getStandardCycles(perm);
        int[] newPerm = cyclesToPerm(cycles, perm.length);
        return Arrays.equals(perm, newPerm);
    }

    static List<int[]> generateFixedPoints(int n) {
        List<int[]> result = new ArrayList<>();
        int[] perm = new int[n];
        for (int i = 0; i < n; i++) perm[i] = i + 1;
        generateFixedPointsHelper(perm, 0, result);
        return result;
    }

    static void generateFixedPointsHelper(int[] perm, int pos, List<int[]> result) {
        if (pos == perm.length) {
            if (isFixedPoint(perm)) {
                result.add(perm.clone());
            }
            return;
        }
        for (int i = pos; i < perm.length; i++) {
            swap(perm, pos, i);
            generateFixedPointsHelper(perm, pos + 1, result);
            swap(perm, pos, i);
        }
    }

    static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long k = sc.nextLong();
        List<int[]> fixedPoints = generateFixedPoints(n);
        fixedPoints.sort((a, b) -> {
            for (int i = 0; i < a.length; i++) {
                if (a[i] != b[i]) return Integer.compare(a[i], b[i]);
            }
            return 0;
        });
        int[] ans = fixedPoints.get((int) (k - 1));
        for (int num : ans) System.out.print(num + " ");
        System.out.println();
    }
}
