import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static List<List<Integer>> cycles = new ArrayList<>();
    static long[] factorial;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long k = sc.nextLong();
        sc.close();

        // Precompute factorials up to n
        factorial = new long[n + 1];
        factorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = factorial[i - 1] * i;
        }

        // Generate all valid cycle structures
        generateCycleStructures(n, n);

        // Sort the cycle structures lexicographically
        cycles.sort((a, b) -> {
            int len = Math.min(a.size(), b.size());
            for (int i = 0; i < len; i++) {
                int cmp = Integer.compare(a.get(i), b.get(i));
                if (cmp != 0) return cmp;
            }
            return Integer.compare(a.size(), b.size());
        });

        // Find the k-th cycle structure
        long total = 0;
        List<Integer> selected = null;
        for (List<Integer> cycle : cycles) {
            long count = countPermutations(cycle, n);
            if (total + count >= k) {
                selected = cycle;
                k -= total;
                break;
            }
            total += count;
        }

        // Generate the k-th permutation with the selected cycle structure
        int[] permutation = generatePermutation(selected, n, k);

        // Output the permutation
        for (int i = 0; i < n; i++) {
            System.out.print(permutation[i] + " ");
        }
        System.out.println();
    }

    static void generateCycleStructures(int remaining, int max) {
        if (remaining == 0) {
            cycles.add(new ArrayList<>());
            return;
        }
        for (int len = 1; len <= Math.min(remaining, max); len++) {
            generateCycleStructures(remaining - len, len);
            // Add the current cycle length to all existing structures
            List<List<Integer>> newCycles = new ArrayList<>();
            for (List<Integer> cycle : cycles) {
                if (cycle.size() == 0 || cycle.get(cycle.size() - 1) != len) {
                    List<Integer> newCycle = new ArrayList<>(cycle);
                    newCycle.add(len);
                    newCycles.add(newCycle);
                }
            }
            cycles.addAll(newCycles);
        }
    }

    static long countPermutations(List<Integer> cycle, int n) {
        long count = factorial[n];
        for (int len : cycle) {
            count /= len;
        }
        return count;
    }

    static int[] generatePermutation(List<Integer> cycle, int n, long k) {
        int[] permutation = new int[n];
        boolean[] used = new boolean[n + 1];
        int index = 0;

        for (int len : cycle) {
            // Find the k-th cycle of length len
            long cycleCount = factorial[n - index] / factorial[n - index - len];
            long cycleIndex = (k - 1) / cycleCount;
            k = (k - 1) % cycleCount + 1;

            // Generate the cycle
            List<Integer> available = new ArrayList<>();
            for (int i = 1; i <= n; i++) {
                if (!used[i]) {
                    available.add(i);
                }
            }

            // Select the cycleIndex-th cycle
            List<Integer> selectedCycle = new ArrayList<>();
            for (int i = 0; i < len; i++) {
                long subCycleCount = factorial[len - i - 1];
                long subIndex = (cycleIndex - 1) / subCycleCount;
                cycleIndex = (cycleIndex - 1) % subCycleCount + 1;

                selectedCycle.add(available.get((int) subIndex));
                available.remove((int) subIndex);
            }

            // Place the cycle in the permutation
            for (int i = 0; i < len; i++) {
                permutation[index + i] = selectedCycle.get(i);
                used[selectedCycle.get(i)] = true;
            }

            index += len;
        }

        return permutation;
    }
}
