public class Main {
    static BufferedReader br;
    static StringTokenizer st;
    static PrintWriter out;
    static long[][] dp;
    static int n;
    static long k;

    public static void main(String[] args) throws Exception {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        n = nextInt();
        k = nextLong();
        dp = new long[n + 2][n + 2];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = -1;
            }
        }
        int[] perm = new int[n + 1];
        solve(1, n, perm);
        for (int i = 1; i <= n; i++) {
            out.print(perm[i] + " ");
        }
        out.println();
        out.close();
    }

    static void solve(int pos, int rem, int[] perm) {
        if (rem == 0) {
            return;
        }
        // Try to place a fixed point at pos
        long fixedCount = count(rem - 1, rem - 1);
        if (k <= fixedCount) {
            perm[pos] = pos;
            solve(pos + 1, rem - 1, perm);
            return;
        }
        k -= fixedCount;
        // Try to place a cycle of length >= 2 starting at pos
        for (int len = 2; len <= rem; len++) {
            long cycleCount = count(rem - len, rem - len);
            if (cycleCount == 0) {
                cycleCount = 1;
            }
            if (k <= cycleCount) {
                // Construct the cycle: pos -> pos+1 -> ... -> pos+len-1 -> pos
                for (int i = 0; i < len - 1; i++) {
                    perm[pos + i] = pos + i + 1;
                }
                perm[pos + len - 1] = pos;
                solve(pos + len, rem - len, perm);
                return;
            }
            k -= cycleCount;
        }
    }

    static long count(int n, int m) {
        if (n == 0) return 1;
        if (dp[n][m] != -1) return dp[n][m];
        long res = 0;
        // Fixed point
        res += count(n - 1, m - 1);
        // Cycle of length >= 2
        for (int len = 2; len <= n; len++) {
            res += count(n - len, m - len);
        }
        return dp[n][m] = res;
    }

    static int nextInt() throws Exception {
        return Integer.parseInt(next());
    }

    static long nextLong() throws Exception {
        return Long.parseLong(next());
    }

    static String next() throws Exception {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        return st.nextToken();
    }
