import java.util.Scanner;

public class Main {
    static List<List<Integer>> cycles = new ArrayList<>();
    static long[] fact;

    static void precomputeFact(int n) {
        fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i;
            if (fact[i] > 1e18) break;
        }
    }

    static long countWays(int n) {
        if (n == 0) return 1;
        if (n == 1) return 1;
        long res = 0;
        for (int len = 2; len <= n; len += 2) {
            long ways = fact[n];
            ways /= fact[len];
            ways /= fact[n - len];
            ways *= countWays(n - len);
            res += ways;
        }
        return res;
    }

    static void generate(int n, long k) {
        if (n == 0) return;
        if (n == 1) {
            cycles.add(new ArrayList<>());
            cycles.get(cycles.size() - 1).add(1);
            return;
        }
        long total = 0;
        for (int len = 2; len <= n; len += 2) {
            long ways = fact[n];
            ways /= fact[len];
            ways /= fact[n - len];
            ways *= countWays(n - len);
            if (k <= total + ways) {
                List<Integer> cycle = new ArrayList<>();
                for (int i = 1; i <= len; i++) cycle.add(i);
                cycles.add(cycle);
                generate(n - len, k - total);
                return;
            }
            total += ways;
        }
    }

    static int[] buildPermutation(int n) {
        int[] perm = new int[n + 1];
        for (List<Integer> cycle : cycles) {
            int m = cycle.size();
            for (int i = 0; i < m; i++) {
                perm[cycle.get(i)] = cycle.get((i + 1) % m);
            }
        }
        return perm;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long k = sc.nextLong();
        precomputeFact(n);
        generate(n, k);
        int[] perm = buildPermutation(n);
        for (int i = 1; i <= n; i++) {
            System.out.print(perm[i] + " ");
        }
        System.out.println();
    }
