        if (currentCycle.size() > 0) {
            cycles.add(new ArrayList<>(currentCycle));
        }
        if (cycles.size() == n) {
            allCycleSets.add(new ArrayList<>(cycles));
            cycles.remove(cycles.size() - 1);
            return;
        }
        for (int i = 1; i <= n; i++) {
            if (currentCycle.size() == 0 || currentCycle.get(currentCycle.size() - 1) < i) {
                currentCycle.add(i);
                generate(n);
                currentCycle.remove(currentCycle.size() - 1);
            }
        }
        if (currentCycle.size() > 0) {
            cycles.remove(cycles.size() - 1);
        }
    }

    static List<Integer> buildPermutation(List<List<Integer>> cycleSet, int n) {
        int[] perm = new int[n + 1];
        for (List<Integer> cycle : cycleSet) {
            for (int i = 0; i < cycle.size(); i++) {
                int from = cycle.get(i);
                int to = cycle.get((i + 1) % cycle.size());
                perm[from] = to;
            }
        }
        List<Integer> result = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            result.add(perm[i]);
        }
        return result;
    }

    public static void main(String[] args) {
