        int n = scanner.nextInt();
        long k = scanner.nextLong();
        scanner.close();

        generate(n);

        List<List<Integer>> validPerms = new ArrayList<>();
        for (List<List<Integer>> cycleSet : allCycleSets) {
            List<Integer> perm = buildPermutation(cycleSet, n);
            if (isStandardForm(cycleSet, n)) {
                validPerms.add(perm);
            }
        }

        validPerms.sort((a, b) -> {
            for (int i = 0; i < a.size(); i++) {
                if (!a.get(i).equals(b.get(i))) {
                    return a.get(i) - b.get(i);
                }
            }
            return 0;
        });

        List<Integer> answer = validPerms.get((int) (k - 1));
        for (int i = 0; i < answer.size(); i++) {
            System.out.print(answer.get(i));
            if (i < answer.size() - 1) {
                System.out.print(" ");
            }
        }
        System.out.println();
    }

    static boolean isStandardForm(List<List<Integer>> cycleSet, int n) {
        for (List<Integer> cycle : cycleSet) {
            int max = cycle.get(0);
            for (int num : cycle) {
                if (num > max) {
                    return false;
                }
            }
        }
        List<Integer> firstElements = new ArrayList<>();
        for (List<Integer> cycle : cycleSet) {
            firstElements.add(cycle.get(0));
        }
        for (int i = 1; i < firstElements.size(); i++) {
            if (firstElements.get(i) < firstElements.get(i - 1)) {
                return false;
            }
        }
        return true;
    }
